class Solution:
    def countRoutes(self, grid: List[str], d: int) -> int:
        MOD = 10 ** 9 + 7
        n, m = len(grid), len(grid[0])
        rv = math.isqrt(d * d - 1)
        A = [1 if grid[n - 1][c] == '.' else 0 for c in range(m)]
        B = [0] * m
        for r in range(n - 2, -1, -1):
            pre = [0] * (m + 1)
            for c in range(m):
                pre[c + 1] = (pre[c] + A[c]) % MOD
            nA = [0] * m
            for c in range(m):
                if grid[r][c] != '.':
                    continue
                lo, hi = max(0, c - rv), min(m - 1, c + rv)
                nA[c] = (pre[hi + 1] - pre[lo]) % MOD
            pre2 = [0] * (m + 1)
            for c in range(m):
                pre2[c + 1] = (pre2[c] + nA[c]) % MOD
            nB = [0] * m
            for c in range(m):
                if grid[r][c] != '.':
                    continue
                lo, hi = max(0, c - d), min(m - 1, c + d)
                nB[c] = (pre2[hi + 1] - pre2[lo] - nA[c]) % MOD
            A, B = nA, nB
        return (sum(A) + sum(B)) % MOD

