class Solution {
public:
    int countRoutes(vector<string>& grid, int d) {
        const long long MOD = 1e9 + 7;
        int n = grid.size(), m = grid[0].size();
        int rv = (int)floor(sqrt((double)d * d - 1));
        while ((long long)(rv + 1) * (rv + 1) <= (long long)d * d - 1) rv++;
        while ((long long)rv * rv > (long long)d * d - 1) rv--;
        vector<long long> A(m), B(m, 0);
        for (int c = 0; c < m; c++) A[c] = grid[n-1][c] == '.' ? 1 : 0;
        for (int r = n - 2; r >= 0; r--) {
            vector<long long> pre(m + 1, 0);
            for (int c = 0; c < m; c++) pre[c+1] = (pre[c] + A[c]) % MOD;
            vector<long long> nA(m, 0), nB(m, 0);
            for (int c = 0; c < m; c++) {
                if (grid[r][c] != '.') continue;
                int lo = max(0, c - rv), hi = min(m - 1, c + rv);
                nA[c] = (pre[hi+1] - pre[lo] % MOD + MOD) % MOD;
            }
            vector<long long> pre2(m + 1, 0);
            for (int c = 0; c < m; c++) pre2[c+1] = (pre2[c] + nA[c]) % MOD;
            for (int c = 0; c < m; c++) {
                if (grid[r][c] != '.') continue;
                int lo = max(0, c - d), hi = min(m - 1, c + d);
                nB[c] = ((pre2[hi+1] - pre2[lo]) % MOD - nA[c] % MOD + 2 * MOD) % MOD;
            }
            A = nA; B = nB;
        }
        long long ans = 0;
        for (int c = 0; c < m; c++) ans = (ans + A[c] + B[c]) % MOD;
        return (int)ans;
    }
};

