var countRoutes = function(grid, d) {
    const MOD = 1e9 + 7;
    const n = grid.length, m = grid[0].length;
    let rv = Math.floor(Math.sqrt(d * d - 1));
    while ((rv + 1) * (rv + 1) <= d * d - 1) rv++;
    while (rv * rv > d * d - 1) rv--;
    let A = Array.from({length: m}, (_, c) => grid[n-1][c] === '.' ? 1 : 0);
    let B = Array(m).fill(0);
    for (let r = n - 2; r >= 0; r--) {
        const pre = Array(m + 1).fill(0);
        for (let c = 0; c < m; c++) pre[c+1] = (pre[c] + A[c]) % MOD;
        const nA = Array(m).fill(0), nB = Array(m).fill(0);
        for (let c = 0; c < m; c++) {
            if (grid[r][c] !== '.') continue;
            const lo = Math.max(0, c - rv), hi = Math.min(m - 1, c + rv);
            nA[c] = ((pre[hi+1] - pre[lo]) % MOD + MOD) % MOD;
        }
        const pre2 = Array(m + 1).fill(0);
        for (let c = 0; c < m; c++) pre2[c+1] = (pre2[c] + nA[c]) % MOD;
        for (let c = 0; c < m; c++) {
            if (grid[r][c] !== '.') continue;
            const lo = Math.max(0, c - d), hi = Math.min(m - 1, c + d);
            nB[c] = (((pre2[hi+1] - pre2[lo]) % MOD - nA[c]) % MOD + MOD) % MOD;
        }
        A = nA; B = nB;
    }
